ConcurrentHashMap 中的 Node 节点中，value 和 next 都是 volatile 的，这样就可以保证对 value 或 next 的更新会被其他线程立即看到。
static class Node < K , V > implements Map . Entry < K , V > { final int hash ; final K key ; volatile V value ; volatile Node < K , V > next ; }

execute 方法没有返回值，适用于不关心结果和异常的简单任务。
threadsPool . execute ( new Runnable () { @Override public void run () { System . out . println ( "execute() 方法提交的任务" ); } });
submit 有返回值，适用于需要获取结果或处理异常的场景。
Future < Object > future = executor . submit ( harReturnValuetask ); try { Object s = future . get (); } catch ( InterruptedException e | ExecutionException e ) { // 处理无法执行任务异常 } finally { // 关闭线程池 executor.shutdown(); }

线程池大小是固定的， corePoolSize == maximumPoolSize ，默认使用 LinkedBlockingQueue 作为阻塞队列，适用于任务量稳定的场景，如数据库连接池、RPC 处理等。
new ThreadPoolExecutor ( 4 , 4 , 0L , TimeUnit . MILLISECONDS , new LinkedBlockingQueue <>());
新任务提交时，如果线程池有空闲线程，直接执行；如果没有，任务进入 LinkedBlockingQueue 等待。缺点是任务队列默认无界，可能导致任务堆积，甚至 OOM。

线程池大小不固定， corePoolSize = 0 ， maximumPoolSize = Integer.MAX_VALUE 。空闲线程超过 60 秒会被销毁，使用 SynchronousQueue 作为阻塞队列，适用于短时间内有大量任务的场景。
new ThreadPoolExecutor ( 0 , Integer . MAX_VALUE , 60L , TimeUnit . SECONDS , new SynchronousQueue <>());
提交任务时，如果线程池没有空闲线程，直接新建线程执行任务；如果有，复用线程执行任务。线程空闲 60 秒后销毁，减少资源占用。缺点是线程数没有上限，在高并发情况下可能导致 OOM。

线程池只有 1 个线程，保证任务按提交顺序执行，使用 LinkedBlockingQueue 作为阻塞队列，适用于需要按顺序执行任务的场景。
new ThreadPoolExecutor ( 1 , 1 , 0L , TimeUnit . MILLISECONDS , new LinkedBlockingQueue <>());
始终只创建 1 个线程，新任务必须等待前一个任务完成后才能执行，其他任务都被放入 LinkedBlockingQueue 排队执行。缺点是无法并行处理任务。

常见的处理方式有，使用 try-catch 捕获、使用 Future 获取异常、自定义ThreadPoolExecutor 重写 afterExecute 方法、使用 UncaughtExceptionHandler 捕获异常。
①、try-catch 是最简单的方法。
executor . execute (() -> { try { System . out . println ( "任务开始" ); int result = 1 / 0 ; // 除零异常 } catch ( Exception e ) { System . err . println ( "捕获异常：" + e . getMessage ()); } });
②、使用 Future 获取异常。
Future < Object > future = executor . submit (() -> { System . out . println ( "任务开始" ); int result = 1 / 0 ; // 除零异常 return result ; }); try { future . get (); } catch ( InterruptedException | ExecutionException e ) { System . err . println ( "捕获异常：" + e . getMessage ()); }
③、自定义 ThreadPoolExecutor 重写 afterExecute 方法。
ThreadPoolExecutor executor = new ThreadPoolExecutor ( 2 , 2 , 0L , TimeUnit . MILLISECONDS , new LinkedBlockingQueue < Runnable >()) { @Override protected void afterExecute ( Runnable r , Throwable t ) { super . afterExecute ( r , t ); if ( t != null ) { System . err . println ( "捕获异常：" + t . getMessage ()); } } }; executor . execute (() -> { System . out . println ( "任务开始" ); int result = 1 / 0 ; // 除零异常 });
④、使用 UncaughtExceptionHandler 捕获异常。
ThreadPoolExecutor executor = new ThreadPoolExecutor ( 2 , 2 , 0L , TimeUnit . MILLISECONDS , new LinkedBlockingQueue < Runnable >()); executor . setRejectedExecutionHandler ( new ThreadPoolExecutor . AbortPolicy ()); executor . setThreadFactory ( new ThreadFactory () { @Override public Thread newThread ( Runnable r ) { Thread thread = new Thread ( r ); thread . setUncaughtExceptionHandler ( new Thread . UncaughtExceptionHandler () { @Override public void uncaughtException ( Thread t , Throwable e ) { System . err . println ( "捕获异常：" + e . getMessage ()); } }); return thread ; } }); executor . execute (() -> { System . out . println ( "任务开始" ); int result = 1 / 0 ; // 除零异常 });
如果项目使用 execute() ，不关心任务返回值，建议使用 UncaughtExceptionHandler：
thread . setUncaughtExceptionHandler (( t , e ) -> System . err . println ( "线程 " + t . getName () + " 捕获到异常：" + e . getMessage ()));
如果项目使用 submit() ，关心任务返回值，建议使用 Future：
Future <?> future = executor . submit ( task ); try { future . get (); } catch ( ExecutionException e ) { System . err . println ( "捕获异常：" + e . getCause ()); }
如果想要全局捕获所有任务异常，建议重写 afterExecute 方法：
class MyThreadPoolExecutor extends ThreadPoolExecutor { @Override protected void afterExecute ( Runnable r , Throwable t ) { if ( t == null && r instanceof Future <?>) { try { (( Future <?>) r ). get (); } catch ( Exception e ) { System . err . println ( "任务异常：" + e . getCause ()); } } } }

线程池的主要目的是为了避免频繁地创建和销毁线程。
我会把线程池看作一个工厂，里面有一群“工人”，也就是线程了，专门用来做任务。
当任务来了，需要先判断有没有空闲的工人，如果有就把任务交给他们；如果没有，就把任务暂存到一个任务队列里，等工人忙完了再去处理。
如果队列满了，还没有空闲的工人，就要考虑扩容，让预备的工人过来干活，但不能超过预定的最大值，防止工厂被挤爆。
如果连扩容也没法解决，就需要一个拒绝策略，可能直接拒绝任务或者报个错。
核心线程池类（可参考）：
class CustomThreadPoolExecutor { private final int corePoolSize ; private final int maximumPoolSize ; private final long keepAliveTime ; private final TimeUnit unit ; private final BlockingQueue < Runnable > workQueue ; private final RejectedExecutionHandler handler ; private volatile boolean isShutdown = false ; private int currentPoolSize = 0 ; // 构造方法 public CustomThreadPoolExecutor ( int corePoolSize , int maximumPoolSize , long keepAliveTime , TimeUnit unit , BlockingQueue < Runnable > workQueue , RejectedExecutionHandler handler ) { this . corePoolSize = corePoolSize ; this . maximumPoolSize = maximumPoolSize ; this . keepAliveTime = keepAliveTime ; this . unit = unit ; this . workQueue = workQueue ; this . handler = handler ; } // 提交任务 public void execute ( Runnable task ) { if ( isShutdown ) { throw new IllegalStateException ( "ThreadPool is shutdown" ); } synchronized ( this ) { // 如果当前线程数小于核心线程数，直接创建新线程 if ( currentPoolSize < corePoolSize ) { new Worker ( task ). start (); currentPoolSize ++; return ; } // 尝试将任务添加到队列中 if (! workQueue . offer ( task )) { if ( currentPoolSize < maximumPoolSize ) { new Worker ( task ). start (); currentPoolSize ++; } else { // 调用拒绝策略 handler . rejectedExecution ( task , null ); } } } } // 关闭线程池 public void shutdown () { isShutdown = true ; } // 工作线程 private class Worker extends Thread { private Runnable task ; Worker ( Runnable task ) { this . task = task ; } @Override public void run () { while ( task != null || ( task = getTask ()) != null ) { try { task . run (); } finally { task = null ; } } } // 从队列中获取任务 private Runnable getTask () { try { return workQueue . poll ( keepAliveTime , unit ); } catch ( InterruptedException e ) { return null ; } } } }
拒绝策略：
/** * 拒绝策略 */ class CustomRejectedExecutionHandler { // AbortPolicy 抛出异常 public static class AbortPolicy implements RejectedExecutionHandler { public void rejectedExecution ( Runnable r , ThreadPoolExecutor e ) { throw new RuntimeException ( "Task " + r . toString () + " rejected from " + e . toString ()); } } // DiscardPolicy 什么都不做 public static class DiscardPolicy implements RejectedExecutionHandler { public void rejectedExecution ( Runnable r , ThreadPoolExecutor e ) { // Do nothing } } // DiscardOldestPolicy 丢弃队列中最旧的任务 public static class CallerRunsPolicy implements RejectedExecutionHandler { public void rejectedExecution ( Runnable r , ThreadPoolExecutor e ) { if (! e . isShutdown ()) { r . run (); } } } }
使用示例：
class ThreadPoolTest { public static void main ( String [] args ) { // 创建线程池 CustomThreadPoolExecutor executor = new CustomThreadPoolExecutor ( 2 , 4 , 10 , TimeUnit . SECONDS , new LinkedBlockingQueue <>( 2 ), new CustomRejectedExecutionHandler . AbortPolicy ()); // 提交任务 for ( int i = 0 ; i < 10 ; i ++) { final int index = i ; executor . execute (() -> { System . out . println ( "Task " + index + " is running" ); try { Thread . sleep ( 2000 ); } catch ( InterruptedException e ) { e . printStackTrace (); } }); } // 关闭线程池 executor . shutdown (); } }
