class SimpleConnectionPool { // 配置 private String jdbcUrl ; private String username ; private String password ; private int maxConnections ; private BlockingQueue < Connection > connectionPool ; // 构造方法 public SimpleConnectionPool ( String jdbcUrl , String username , String password , int maxConnections ) throws SQLException { this . jdbcUrl = jdbcUrl ; this . username = username ; this . password = password ; this . maxConnections = maxConnections ; this . connectionPool = new LinkedBlockingQueue <>( maxConnections ); // 初始化连接池 for ( int i = 0 ; i < maxConnections ; i ++) { connectionPool . add ( createNewConnection ()); } } // 创建新连接 private Connection createNewConnection () throws SQLException { return DriverManager . getConnection ( jdbcUrl , username , password ); } // 获取连接 public Connection getConnection ( long timeout , TimeUnit unit ) throws InterruptedException , SQLException { Connection connection = connectionPool . poll ( timeout , unit ); // 等待指定时间获取连接 if ( connection == null ) { throw new SQLException ( "Timeout: Unable to acquire a connection." ); } return connection ; } // 归还连接 public void releaseConnection ( Connection connection ) throws SQLException { if ( connection != null ) { if ( connection . isClosed ()) { // 如果连接已关闭，创建一个新连接补充到池中 connectionPool . add ( createNewConnection ()); } else { // 将连接归还到池中 connectionPool . offer ( connection ); } } } // 关闭所有连接 public void closeAllConnections () throws SQLException { for ( Connection connection : connectionPool ) { if (! connection . isClosed ()) { connection . close (); } } } // 测试用例 public static void main ( String [] args ) { try { SimpleConnectionPool pool = new SimpleConnectionPool ( "jdbc:mysql://localhost:3306/pai_coding" , "root" , "" , 5 ); // 获取连接 Connection conn = pool . getConnection ( 5 , TimeUnit . SECONDS ); // 使用连接（示例查询） System . out . println ( "Connection acquired: " + conn ); Thread . sleep ( 2000 ); // 模拟查询 // 归还连接 pool . releaseConnection ( conn ); System . out . println ( "Connection returned." ); // 关闭所有连接 pool . closeAllConnections (); } catch ( Exception e ) { e . printStackTrace (); } } }
